vel' AND e.after_level = 3), 'اكتشف الخطأ: شركة طبقت الإعفاء الشخصي والشرائح على موظف بدوام جزئي عنده جهة عمل أصلية تانية. التصحيح:', '["تخصم 5% بس","التطبيق صح لأن كل موظف ليه إعفاء","تخصم 10% قطعي لأنها جهة غير أصلية، والإعفاء من الجهة الأصلية بس","ماتخصمش حاجة لأن الجهة الأصلية بتخصم"]', 2, 'كده الإعفاء بيتاخد مرتين، والفرق بيطلع على الشركة في الفحص. (الوحدة 3.4)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: شركة طبقت الإعفاء الشخصي والشرائح على موظف بدوام جزئي عنده جهة عمل أصلية تانية. التصحيح:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'اكتشف الخطأ: سارة خصمت من محمود 592.50 بس في ديسمبر رغم إنه خد مكافأة 12,000. التصحيح:', '["592.50 صح لأن المكافأة معفاة","خصم ديسمبر 1,200 (10% من المكافأة)","المكافأة تتأجل لتسوية يناير من غير خصم","خصم ديسمبر 2,992.50 على أساس الحسبة السنوية، وإلا يطلع فرق 2,400 في التسوية"]', 3, 'الضريبة السنوية 9,510 − 6,517.50 المخصوم = 2,992.50. الفرق 2,400 الشركة هتتلزم تسدده لو ماتخصمش. (الوحدة 3.5)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: سارة خصمت من محمود 592.50 بس في ديسمبر رغم إنه خد مكافأة 12,000. التصحيح:'); UPDATE courses SET subtitle = 'منطق المعايير الدولية وتطبيقها العملي، معيار معيار وكل معيار وحدة', intro = 'كورس بيشرح المعايير الدولية للتقرير المالي IFRS بالمنطق قبل الحفظ. كل مستوى عبارة عن فصل بيجمع معايير بتجاوب على سؤال واحد، وكل معيار وحدة مستقلة بتمشي بنفس الترتيب: الحكاية والمشكلة المحاسبية، النطاق والتعريفات، الاعتراف والقياس الأولي واللاحق، حالة عملية بالأرقام والقيود، الأثر على القوائم والإفصاح، الأخطاء الشائعة، والخلاصة وأسئلة تقييم بمفتاح الإجابة. هنفرّق في كل نقطة بين متطلب المعيار والتفسير التعليمي والاجتهاد المهني، ونربط بالواقع المصري زي ضريبة القيمة المضافة القابلة للخصم. كل الشركات والأسماء في الأمثلة خيالية، والمراجع بأرقام فقرات المعايير عشان ترجعلها بنفسك.', audience = 'المحاسبين الـ Junior والـ Senior، ودارسي ACCA وDipIFRS وCMA، ومحاسبي الشركات اللي بتطبق IFRS أو بتجهز قوايم للشركة الأم' WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'الأصول غير المالية: من يوم الشراء لحد الميزانية', 'الوحدة 1: IAS 16 العقارات والآلات والمعدات. الوحدة 2: IAS 38 الأصول غير الملموسة. الوحدة 3: IAS 2 المخزون. الوحدة 4: IAS 40 الاستثمار العقاري.', 'عقار واحد ممكن يبقى أصل ثابت أو مخزون أو استثمار عقاري، وكل تصنيف ليه قياس مختلف. هنعرف الأصل يدخل الدفاتر بكام، ويفضل متقاس بكام بعد كده، وليه الـ 14% اللي على الفاتورة مش تكلفة.' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'أصول ليها طبيعة خاصة، وإمتى القيمة تقع', 'الوحدة 1: IAS 41 الزراعة. الوحدة 2: IAS 20 المنح الحكومية. الوحدة 3: IFRS 6 استكشاف وتقييم الموارد المعدنية. الوحدة 4: IAS 36 الاضمحلال في قيمة الأصول.', 'مزرعة مواشي بتكبر كل يوم، ومنحة من الحكومة بشروط، وشركة بتحفر بحثًا عن بترول، ومصنع السوق وقع عليه. هنعرف كل أصل من دول يتقاس إزاي، وإمتى الرقم اللي في الدفاتر يبقى أكبر من الحقيقة.' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'الإيراد: إمتى نقول اتباع؟', 'الوحدة 1: IFRS 15 نموذج الخطوات الخمس. الوحدة 2: التزامات الأداء وتخصيص السعر والمقابل المتغير. الوحدة 3: الإيراد على مدار الوقت وعقود الإنشاء. الوحدة 4: حالات خاصة: الوكيل والأصيل، والضمان، والترخيص.', 'عقد واحد فيه جهاز وتركيب وصيانة 3 سنين، والعميل دفع مقدم. نعترف بالإيراد كله النهارده؟ ولا على مراحل؟' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'الإيجارات', 'الوحدة 1: IFRS 16 تعريف عقد الإيجار ومين المستأجر. الوحدة 2: المحاسبة عند المستأجر: أصل حق الاستخدام والتزام الإيجار. الوحدة 3: المحاسبة عند المؤجر. الوحدة 4: التعديلات والبيع مع إعادة الاستئجار.', 'الشركة أجّرت مخزن 5 سنين. زمان كان مصروف إيجار وخلاص، دلوقتي بقى أصل والتزام في الميزانية. ليه؟ وإزاي ده بيغير شكل المديونية؟' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'الأدوات المالية', 'الوحدة 1: IAS 32 الالتزام ولا حقوق الملكية. الوحدة 2: IFRS 9 التصنيف والقياس. الوحدة 3: IFRS 9 الخسائر الائتمانية المتوقعة. الوحدة 4: IFRS 7 الإفصاح ولمحة عن محاسبة التحوط.', 'سند بفايدة، وسهم في البورصة، وعملا متأخرين في السداد. كل واحد فيهم أداة مالية، بس كل واحد ليه قياس ومكان مختلف في القوايم.' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'الالتزامات والضرايب والأحداث', 'الوحدة 1: IAS 37 المخصصات والالتزامات والأصول المحتملة. الوحدة 2: IAS 12 ضرايب الدخل والضريبة المؤجلة. الوحدة 3: IAS 10 الأحداث بعد تاريخ التقرير. الوحدة 4: IAS 8 السياسات والتقديرات وتصحيح الأخطاء.', 'قضية في المحكمة، وفرق بين الإهلاك المحاسبي والضريبي، وحريق حصل بعد آخر السنة وقبل اعتماد القوايم. كل ده يتسجل؟ ولا يتفصح عنه؟ ولا ولا حاجة؟' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'المجموعات والعملات', 'الوحدة 1: IFRS 3 تجميع الأعمال والشهرة. الوحدة 2: IFRS 10 القوايم المجمعة. الوحدة 3: IAS 28 وIFRS 11 الشركات الشقيقة والترتيبات المشتركة. الوحدة 4: IAS 21 أثر التغير في أسعار الصرف.', 'الشركة اشترت 70% من منافس وعندها فرع بالدولار. هنجمع القوايم ونحسب الشهرة وحقوق الأقلية، ونترجم أرقام الفرع بعد تعويم الجنيه.' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 8, 'العرض والإفصاح وقياس القيمة العادلة', 'الوحدة 1: IFRS 18 العرض والإفصاح (بديل IAS 1). الوحدة 2: IAS 7 قائمة التدفقات النقدية. الوحدة 3: IFRS 13 قياس القيمة العادلة. الوحدة 4: IAS 33 ربحية السهم وIAS 24 الأطراف ذوي العلاقة.', 'كل اللي اتعلمناه لازم يطلع في قوايم يقراها المستثمر والبنك. هنقفل الكورس بقوايم كاملة على شكل IFRS 18 الجديد، وتدفقات نقدية، وإيضاحات.' FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 8, 'امتحان المستوى 8', 10, 50, 15 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 4, 'الامتحان التراكمي الأول (المستويات 1 إلى 4)', 20, 50, 40 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO exams (course_id, kind, aft