وقيمة استخدامها 720,000. الخسارة:', '["80,000","150,000","70,000","صفر"]', 0, 'القيمة القابلة للاسترداد 720,000، والخسارة 800,000 − 720,000.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'آلة قيمتها الدفترية 800,000، وقيمتها العادلة ناقص تكاليف الاستبعاد 650,000، وقيمة استخدامها 720,000. الخسارة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'أصل قيمته الدفترية 500,000 وقيمته العادلة ناقص تكاليف الاستبعاد 530,000. قيمة الاستخدام:', '["لازم تتحسب","لازم تكون أكبر من 530,000","مش لازم تتحسب لأن مفيش اضمحلال","بتتحسب بس لو أقل"]', 2, 'لو أي قيمة منهم أكبر من القيمة الدفترية مفيش اضمحلال (IAS 36.19).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'أصل قيمته الدفترية 500,000 وقيمته العادلة ناقص تكاليف الاستبعاد 530,000. قيمة الاستخدام:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'أنهي بند مايدخلش في تكاليف الاستبعاد؟', '["المصاريف القانونية للبيع","تكاليف فك ونقل الأصل","ضريبة الدخل على مكسب البيع","رسوم الدمغة"]', 2, 'ضرائب الدخل وتكاليف التمويل مستبعدة (IAS 36.6 و36.28).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'أنهي بند مايدخلش في تكاليف الاستبعاد؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'عند تقدير قيمة الاستخدام حسب المعيار الساري، التدفقات من تحسين مستقبلي لأداء الأصل:', '["تدخل لو محتملة","تدخل لو الإدارة وافقت عليها","تدخل بنسبة 50%","ماتدخلش لأن التقدير للأصل بحالته الحالية"]', 3, 'IAS 36.44. فيه اقتراح من IASB بتغيير ده لكنه لسه ماصدرش.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'عند تقدير قيمة الاستخدام حسب المعيار الساري، التدفقات من تحسين مستقبلي لأداء الأصل:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'أنهي أصل لازم يتختبر سنويًا حتى لو مفيش مؤشر؟', '["شهرة ناتجة عن تجميع أعمال","مبنى بنموذج التكلفة","عربية نقل","مخزون"]', 0, 'IAS 36.10.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'أنهي أصل لازم يتختبر سنويًا حتى لو مفيش مؤشر؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'أصل بنموذج إعادة التقييم ليه فائض 40,000، وطلعت عليه خسارة اضمحلال 100,000. المعالجة:', '["100,000 أرباح وخسائر","40,000 دخل شامل آخر و60,000 أرباح وخسائر","100,000 دخل شامل آخر","60,000 دخل شامل آخر و40,000 أرباح وخسائر"]', 1, 'بتتعامل كتخفيض إعادة تقييم (IAS 36.61).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'أصل بنموذج إعادة التقييم ليه فائض 40,000، وطلعت عليه خسارة اضمحلال 100,000. المعالجة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'خط قيمته الدفترية بعد الاضمحلال 1,750,000 وعمره المتبقي 10 سنين. الإهلاك السنوي بعد كده:', '["175,000","200,000","150,000","250,000"]', 0, '1,750,000 ÷ 10 (IAS 36.63).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'خط قيمته الدفترية بعد الاضمحلال 1,750,000 وعمره المتبقي 10 سنين. الإهلاك السنوي بعد كده:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'قيمته الدفترية الحالية 1,400,000، ولو ماكانش فيه اضمحلال كانت هتبقى 1,600,000، وقيمته القابلة للاسترداد الجديدة 1,700,000. رد الخسارة:', '["300,000","100,000","صفر","200,000"]', 3, 'السقف 1,600,000، فالرد 1,600,000 − 1,400,000 (IAS 36.117).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'قيمته الدفترية الحالية 1,400,000، ولو ماكانش فيه اضمحلال كانت هتبقى 1,600,000، وقيمته القابلة للاسترداد الجديدة 1,700,000. رد الخسارة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'خسارة اضمحلال الشهرة:', '["بترتد لو الظروف اتحسنت","مابترتدش أبدًا","بترتد في الدخل الشامل الآخر","بترتد بعد 5 سنين"]', 1, 'IAS 36.124.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'خسارة اضمحلال الشهرة:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2), 'خسارة اضمحلال وحدة توليد نقد فيها شهرة بتتوزع:', '["بالتساوي على كل الأصول","على الشهرة الأول، والباقي على الأصول بنسبة قيمها الدفترية","على الأصول الملموسة بس","على أكبر أصل"]', 1, 'IAS 36.104.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'ifrs' AND e.kind = 'level' AND e.after_level = 2) AND body = 'خسارة اضمحلال وحدة توليد نقد فيها شهرة بتتوزع:'); CREATE TABLE IF NOT EXISTS study_time ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, material_id INTEGER NOT NULL REFERENCES materials(id) ON DELETE CASCADE, day TEXT NOT NULL, minutes INTEGER NOT NULL DEFAULT 0, last_at TEXT, PRIMARY KEY (user_id, material_id, day) ); CREATE TABLE plans_new (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, features TEXT, price REAL NOT NULL DEFAULT 0, show_price INTEGER NOT NULL DEFAULT 0, discount_type TEXT NOT NULL DEFAULT 'none' CHECK (discount_type IN ('none','percent','amount')), discount_value REAL NOT NULL DEFAULT 0, discount_ends TEXT, visible INTEGER NOT NULL DEFAULT 1, full_access INTEGER NOT NULL DEFAULT 0, apps TEXT NOT NULL DEFAULT '[]', sort INTEGER NOT NULL DEFAULT 0, UNIQUE (course_id, code)); INSERT INTO plans_new (id, course_id, code, name, features, price, show_price, discount_type, discount_value, discount_ends, visible, full_access, apps, sort) SELECT id, course_id, code, name, features, price, show_price, discount_type, discount_value, discount_ends, visible, CASE WHEN code = 'pro' THEN 1 ELSE 0 END, '[]', CASE WHEN code = 'pro' THEN 2 ELSE 1 END FROM plans; DROP TABLE plans; ALTER TABLE plans_new RENAME TO plans; CREATE TABLE enrollments_new (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, plan_code TEXT NOT NULL DEFAULT 'basic', starts_at TEXT NOT NULL DEFAULT (date('now')), expires_at TEXT, UNIQUE (user_id, course_id)); INSERT INTO enrollments_new (id, user_id, course_id, plan_code, starts_at, expires_at) SELECT id, user_id, course_id, plan_code, starts_at, expires_at FROM enrollments; DROP TABLE enrollments; ALTER TABLE enrollments_new RENAME TO enrollments;
